  for (let y = 4; y <= 49; y += 0.25) P(G, 6.2 - (y - 4) * 0.04, y, y < 6 ? 'A' : y % 3 < 1.5 ? 'R' : 'r');          // 流れ落ちる深紅（座まで）
  for (const [x, y, ch] of [[5.0, 12, 'R'], [7.2, 20, 'r'], [5.1, 30, 'R'], [7.0, 38, 'r'], [5.3, 46, 'r']]) P(G, x, y, ch);
