  crescent(G, 17.5, 12.5, 12.4, 9.0, 2.0, 9.8, { rim: 'r', rimW: 1.4, mid: 'q', dark: 'k' });                          // 奥の刃＝欠けの円を主の刃と共有させ、外へ 6 ドットだけ覗かせる＝同じ月牙がもう一枚後ろに重なる「列」。共有しないと下の角が破片のように散る
