  P(G, 22.4, 5.6, 'A'); P(G, 30.5, 23.4, 'A');                                                                            // 両端の切っ先の光
  DISC(G, 14, 20.5, 2.4, 'k'); DISC(G, 14, 20.5, 1.8, 'R'); P(G, 13.5, 20, 'A');                                        // 深紅の玉（刃の厚い所）
  OUTLINE(G);
