      const tR = ((x - A[0]) * (Pk[0] - A[0]) + (y - A[1]) * (Pk[1] - A[1])) / RL2, dR = ds(A, Pk, x, y), dPk = Math.hypot(x - Pk[0], y - Pk[1]);
      const emb = Math.min(ds(q[1], q[2], x, y), ds(q[2], q[3], x, y)), up = Math.sign(cr(A, Pk, x, y)) === upSign;
