// 【第二案 第13稿】機械の頭と襟の装甲（dome）。FB「いまの蒼神骸華に、いまの顔がもはやあわない。顔と肩まわりを修正して」＝金の冕冠・骨の角・玉の簾・排気管・鈴・配線を外す。
